namespace UnturnedModManager {
 public static class ExperienceTests {
  static Package Fixture(string folder,string id,string name,string version,string target){Directory.CreateDirectory(folder);string source="payload/"+target;string path=Paths.Safe(folder,source);Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,id+version);Data.Write(Path.Combine(folder,Packages.ManifestName),new PackageManifest{schemaVersion=1,id=id,name=name,version=version,kind="module",description="Author description / 作者說明",files=new List<PackageFile>{new PackageFile{source=source,target=target,sha256=Data.Hash(path)}}});return Packages.Load(folder,L.Get("Text227"));}
  public static int Run(string output){string root=Path.Combine(Path.GetFullPath(output),"ui-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);L.Validate();var results=new List<string>();
   foreach(string code in L.Languages){L.Language=code;string state=Path.Combine(root,code);string game=Path.Combine(state,"game");Directory.CreateDirectory(game);File.WriteAllText(Path.Combine(game,"Unturned.exe"),"fake");string source=Path.Combine(state,"packages");Directory.CreateDirectory(source);
    var old=Fixture(Path.Combine(source,"alpha-old"),"test.alpha","Alpha test mod","1.0.0","Modules/Alpha/a.dll");var newer=Fixture(Path.Combine(source,"alpha-new"),"test.alpha","Alpha test mod","2.0.0","Modules/Alpha/a.dll");Fixture(Path.Combine(source,"beta"),"test.beta","Beta 測試模組","1.0.0","Modules/Beta/b.dll");Fixture(Path.Combine(source,"conflict"),"test.conflict","Conflicting mod","1.0.0","Modules/Alpha/a.dll");
    var engine=new Engine(game,state,true);engine.Install(old,null);Data.Write(Path.Combine(state,"settings.json"),new Settings{language=code,gameRoot=game,workshopRoot=source,packageFolders=new List<string>(),versionChoices=new Dictionary<string,string>()});
    using(var form=new MainForm(root,state,true)){Exception failure=null;form.Shown+=async delegate{try{await form.VerifyExperience(root,results);}catch(Exception ex){failure=ex;}finally{form.EndFixture();form.Close();}};Application.Run(form);if(failure!=null)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure).Throw();}
    using(var restart=new MainForm(root,state,true)){if(L.Language!="zh-CN")throw new Exception("Language preference did not survive restart");}
    L.Language=code;engine.Install(newer,null);engine.Uninstall(old.Manifest.id);if(File.Exists(Path.Combine(game,"Modules/Alpha/a.dll")))throw new Exception("Localized uninstall failed");
    try{Paths.Safe(game,"../escape");throw new Exception("Unsafe path accepted");}catch(Exception ex){if(!ex.Message.StartsWith(L.Get("Text139"))||!Problems.Explain(ex).StartsWith(L.Get("Text139")))throw;}
    if(!Problems.Explain(new UnauthorizedAccessException("test")).Contains(L.Get("Text186")))throw new Exception("Missing localized remedy");results.Add("PASS "+code+": resource coverage, restart persistence, localized install/update/uninstall and errors");
   }
   string stressRoot=Directory.GetDirectories(Path.GetFullPath(output),"workflow-*").OrderByDescending(Directory.GetLastWriteTimeUtc).FirstOrDefault();if(stressRoot!=null){string stressGame=Path.Combine(stressRoot,"Library","steamapps","common","Unturned"),stressState=Path.Combine(root,"large-state");Data.Write(Path.Combine(stressState,"settings.json"),new Settings{language="zh-TW",gameRoot=stressGame,workshopRoot=Path.Combine(stressRoot,"sources"),packageFolders=new List<string>(),versionChoices=new Dictionary<string,string>()});using(var form=new MainForm(root,stressState,true)){Exception failure=null;form.Shown+=delegate{try{form.VerifyLargeLibrary(root,results);}catch(Exception ex){failure=ex;}finally{form.EndFixture();form.Close();}};Application.Run(form);if(failure!=null)System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failure).Throw();}}
   L.Language="invalid";if(L.Language!="zh-TW")throw new Exception("Invalid culture fallback failed");if(L.Get("unknown")!="[unknown]")throw new Exception("Unknown key fallback failed");results.Add("PASS invalid culture and unknown key fallbacks");File.WriteAllLines(Path.Combine(root,"ui-results.txt"),results);Console.WriteLine(string.Join(Environment.NewLine,results));Console.WriteLine("UI artifacts: "+root);return 0;
  }
 }
 public partial class MainForm {
  void AssertExperience(bool condition,string message,List<string> results){if(!condition)throw new Exception(message);results.Add("PASS "+L.Language+": "+message);Console.WriteLine(results.Last());}
  public void VerifyLargeLibrary(string output,List<string> results){AssertExperience(rows.Count==120&&rows.Sum(r=>r.Options.Count)==720,"large library renders 120 same-name mod identities and 720 versions",results);AssertExperience(grid.Rows.Cast<DataGridViewRow>().Select(r=>Convert.ToString(r.Cells[1].Value)).Distinct().Count()==120,"same-name mods show distinguishing IDs",results);int scans=scanRuns;var timer=System.Diagnostics.Stopwatch.StartNew();search.Text="stress.mod119";AssertExperience(grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible)==1,"large library searches by ID without disk scanning",results);long searchMs=timer.ElapsedMilliseconds;search.Clear();expanded.Clear();RefreshVersions();AssertExperience(versionGrid.RowCount==120,"large version view creates only collapsed parent rows",results);foreach(var row in rows)expanded.Add(RowId(row));timer.Restart();RefreshVersions();long expandMs=timer.ElapsedMilliseconds;AssertExperience(versionGrid.RowCount==840&&scanRuns==scans,"expanding 720 versions never rescans the disk",results);for(int i=0;i<5;i++){expanded.Clear();RefreshVersions();expanded.Add(RowId(rows[i]));RefreshVersions();}AssertExperience(versionGrid.RowCount==126,"repeated expansion realizes only one chosen group",results);results.Add("BENCHMARK UI search="+searchMs+"ms expand-all="+expandMs+"ms; mods=120; versions=720");Console.WriteLine(results.Last());tabs.SelectedIndex=1;PerformLayout();Application.DoEvents();using(var image=new Bitmap(ClientSize.Width,ClientSize.Height)){Controls[0].DrawToBitmap(image,new Rectangle(Point.Empty,ClientSize));image.Save(Path.Combine(output,"large-version-groups.png"));}}
  internal void EndFixture(){if(preview)SetBusy(false);}
  IEnumerable<Control> Descendants(Control control){foreach(Control child in control.Controls){yield return child;foreach(Control nested in Descendants(child))yield return nested;}}
  async System.Threading.Tasks.Task ExecuteFixtureOperation(Func<System.Threading.Tasks.Task> operation,string categoryText=null){
   if(!preview||!game.Text.StartsWith(Path.GetDirectoryName(store),StringComparison.OrdinalIgnoreCase))throw new Exception("UI operation fixture guard failed");
   using(var timer=new System.Windows.Forms.Timer{Interval=30}){timer.Tick+=delegate{foreach(Form dialog in Application.OpenForms.Cast<Form>().Where(f=>f!=this).ToArray()){if(categoryText!=null){var edit=Descendants(dialog).OfType<TextBox>().FirstOrDefault(t=>!t.ReadOnly);if(edit!=null)edit.Text=categoryText;}var buttons=Descendants(dialog).OfType<System.Windows.Forms.Button>().ToList();var confirm=buttons.FirstOrDefault(b=>b.DialogResult==DialogResult.Yes)??buttons.FirstOrDefault(b=>b.DialogResult==DialogResult.OK);if(confirm!=null)confirm.PerformClick();}};timer.Start();var task=operation();if(await System.Threading.Tasks.Task.WhenAny(task,System.Threading.Tasks.Task.Delay(30000))!=task)throw new Exception("UI fixture operation timed out");await task;timer.Stop();}

  }
  async System.Threading.Tasks.Task VerifyModernInteractions(List<string> results){
   tabs.SelectedIndex=0;search.Text="Beta";CheckVisible(true);int before=scanRuns;await ExecuteFixtureOperation(()=>Install());AssertExperience(rows.Single(r=>RowId(r)=="test.beta").Installed!=null&&search.Text=="Beta","actual install workflow updates registry and preserves search",results);AssertExperience(scanRuns==before,"install refreshes records without rescanning sources",results);await ExecuteFixtureOperation(()=>Uninstall());AssertExperience(rows.Single(r=>RowId(r)=="test.beta").Installed==null&&search.Text=="Beta","actual uninstall workflow restores files and preserves search",results);
   settings.categories.Add("UI fixture");RefreshCategories();assignCategory.SelectedItem="UI fixture";AssignCategory();search.Text="UI fixture";AssertExperience(grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible)==1,"category assignment participates in in-memory search",results);categoryList.SelectedItem="UI fixture";await ExecuteFixtureOperation(delegate{EditCategory(true);return System.Threading.Tasks.Task.FromResult(0);},"Renamed fixture");AssertExperience(settings.categories.Contains("Renamed fixture")&&settings.modCategories["test.beta"].Contains("Renamed fixture"),"category rename updates assignments without moving files",results);categoryList.SelectedItem="Renamed fixture";await ExecuteFixtureOperation(delegate{RemoveCategory();return System.Threading.Tasks.Task.FromResult(0);});AssertExperience(settings.categories.Count==0&&Directory.Exists(rows.Single(r=>RowId(r)=="test.beta").Package.Folder),"removing a category preserves source files",results);
   search.Clear();filter.SelectedIndex=0;categoryFilter.SelectedIndex=0;checkedVersions.Clear();expanded.Clear();RefreshVersions();AssertExperience(versionGrid.Rows.Count==3,"collapsed version view realizes one row per mod",results);expanded.Add("test.alpha");RefreshVersions();AssertExperience(versionGrid.Rows.Count==5,"expansion adds only the chosen mod versions",results);versionGrid.Rows[0].Cells[0].Value=CheckState.Checked;AssertExperience(CheckedOptions().Count==2&&!installVersions.Enabled,"parent selection checks all children and rejects ambiguous batch install",results);versionGrid.Rows[1].Cells[0].Value=CheckState.Unchecked;AssertExperience((CheckState)versionGrid.Rows[0].Cells[0].Value==CheckState.Indeterminate,"partial version selection is reflected by the parent checkbox",results);checkedVersions.Clear();var latest=rows.Single(r=>RowId(r)=="test.alpha").Options[0];SetVersionChecked(latest,true);RefreshVersions();tabs.SelectedIndex=1;await ExecuteFixtureOperation(()=>InstallCheckedVersions());AssertExperience(rows.Single(r=>RowId(r)=="test.alpha").Installed.version=="2.0.0","checked version action installs the intended version",results);AssertExperience(scanRuns==before,"version switching uses cached source catalog and refreshes installation state",results);SaveExpanded();AssertExperience(Data.Read<Settings>(Path.Combine(store,"settings.json")).expandedGroups.Contains("test.alpha"),"expanded mod identity is persisted",results);checkedVersions.Clear();RefreshVersions();
   tabs.SelectedIndex=0;search.Clear();CheckVisible(false);string oldGame=game.Text;game.Text=game.Text+"-changed";AssertExperience(!CatalogMatchesTarget()&&!installButton.Enabled&&!uninstallButton.Enabled,"editing a target disables operations until a rescan",results);game.Text=oldGame;
   string zip=Path.Combine(store,"ui-import.zip");System.IO.Compression.ZipFile.CreateFromDirectory(rows.Single(r=>RowId(r)=="test.beta").Package.Folder,zip);var import=Packages.ImportZip(zip,store);await Scan();var importedVersion=rows.Single(r=>RowId(r)=="test.beta").Options.Single(o=>Data.Same(o.Key,import.Folder));checkedVersions.Clear();SetVersionChecked(importedVersion,true);RefreshVersions();await ExecuteFixtureOperation(()=>ArchiveCheckedVersions());AssertExperience(!Directory.Exists(import.Folder)&&Directory.GetDirectories(Path.Combine(store,"RemovedImports")).Length==1,"batch archive moves imported files to a recoverable container",results);AssertExperience(Directory.Exists(rows.Single(r=>RowId(r)=="test.beta").Package.Folder),"archiving preserves the independent original source",results);checkedVersions.Clear();SetVersionChecked(rows.Single(r=>RowId(r)=="test.beta").Options[0],true);await ExecuteFixtureOperation(()=>ArchiveCheckedVersions());AssertExperience(Directory.Exists(rows.Single(r=>RowId(r)=="test.beta").Package.Folder),"batch archive refuses unmanaged sources",results);checkedVersions.Clear();RefreshVersions();
   tabs.SelectedIndex=0;var history=activityEntries.ToList();for(int i=0;i<3100;i++)AddActivity("bounded activity "+i);AssertExperience(activityEntries.Count==3000,"activity history has a bounded memory footprint",results);activityEntries.Clear();activityEntries.AddRange(history);AddActivity("needle warning","WarningLog","Alpha test mod",L.Get("Operation"));activityKind.SelectedIndex=3;activitySearch.Text="needle";RefreshActivity();AssertExperience(visibleActivity.Count==1&&activityGrid.VirtualMode,"activity severity and search use the virtualized log view",results);activityKind.SelectedIndex=0;activitySearch.Clear();
   scanCancellation=new System.Threading.CancellationTokenSource();SetBusy(true,true);cancelScan.PerformClick();AssertExperience(scanCancellation.IsCancellationRequested,"cancel button signals the current scan",results);scanCancellation.Dispose();scanCancellation=null;SetBusy(false);AssertExperience(Directory.GetFiles(Path.Combine(store,"SettingsBackups"),"*.json").Length>0,"settings migration preserves a prior settings snapshot",results);
  }
  public async System.Threading.Tasks.Task VerifyExperience(string output,List<string> results){string original=L.Language;AssertExperience(rows.Count==3,"scan groups versions and retains distinct mod IDs",results);AssertExperience(rows.Any(r=>r.Conflict!=null),"ownership conflict is visible before installation",results);
   search.Text="Beta";CheckVisible(true);AssertExperience(Selected().Count==1&&Selected()[0].Package.Manifest.id=="test.beta","search and bulk select affect the visible mod",results);search.Text="Alpha";AssertExperience(Selected().Count==0,"hidden checks are cleared before batch actions",results);
   search.Text="does not exist";AssertExperience(empty.Visible,"empty search guidance is visible",results);search.Clear();filter.SelectedIndex=1;AssertExperience(grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible)==1,"installed filter",results);filter.SelectedIndex=3;AssertExperience(grid.Rows.Cast<DataGridViewRow>().Count(r=>r.Visible)==1,"update filter",results);filter.SelectedIndex=0;
   CheckVisible(true);sort.SelectedIndex=1;AssertExperience(Selected().Count==3&&rows[0].Package.Manifest.name=="Conflicting mod","sorting retains checked mod identity",results);sort.SelectedIndex=0;CheckVisible(false);AssertExperience(!installButton.Enabled&&!uninstallButton.Enabled,"batch actions require a valid selection",results);
   foreach(string code in L.Languages){ChangeLanguage(Array.IndexOf(L.Languages,code));AssertExperience(tabs.TabPages[3].Text==L.Get("Settings")&&grid.Columns[3].HeaderText==L.Get("Text030"),"live language updates navigation and columns",results);AssertExperience(rows[0].Options[0].Label.Contains(L.Get("Text230")),"version recommendation relocalizes",results);}
   ChangeLanguage(Array.IndexOf(L.Languages,original));await VerifyModernInteractions(results);
   foreach(Size size in new[]{new Size(1280,920),new Size(1060,780),new Size(1000,680),new Size(1530,800),new Size(1850,980)}){ClientSize=size;PerformLayout();Application.DoEvents();AssertExperience(languageChoice.Bounds.Right<=languageChoice.Parent.ClientSize.Width&&languageChoice.Bounds.Left>=0,"header language selector stays within bounds",results);tabs.SelectedIndex=0;LayoutDetail();Application.DoEvents();AssertExperience(grid.Height>=100,"compact layout reserves space for usable mod rows",results);AssertExperience(filters.PointToScreen(new Point(0,filters.Height)).Y<=detailSplit.PointToScreen(Point.Empty).Y&&filters.Height>=96,"search tools have a reserved visible layout region",results);foreach(int page in new[]{0,1,2,3}){tabs.SelectedIndex=page;PerformLayout();Application.DoEvents();using(var bitmap=new Bitmap(ClientSize.Width,ClientSize.Height)){Controls[0].DrawToBitmap(bitmap,new Rectangle(Point.Empty,ClientSize));bitmap.Save(Path.Combine(output,original+"-"+size.Width+"-page"+page+".png"));}}}
   tabs.SelectedIndex=0;foreach(float factor in new[]{1.25f,1.5f,1.75f,2f}){Size saved=ClientSize;Scale(new SizeF(factor,factor));ClientSize=new Size((int)(saved.Width*factor),(int)(saved.Height*factor));PerformLayout();Application.DoEvents();LayoutDetail();detailSplit.PerformLayout();grid.Parent.PerformLayout();FitGrid(grid,new float[]{12,75,90,60,30});FitGrid(versionGrid,new float[]{12,12,75,40,40,90,45});AssertExperience(grid.Columns.Cast<DataGridViewColumn>().Sum(c=>c.Width)<=grid.ClientSize.Width&&languageChoice.Right<=languageChoice.Parent.ClientSize.Width&&grid.Height>80,"scaled layout at "+factor,results);using(var image=new Bitmap(ClientSize.Width,ClientSize.Height)){Controls[0].DrawToBitmap(image,new Rectangle(Point.Empty,ClientSize));image.Save(Path.Combine(output,original+"-scale-"+factor.ToString(System.Globalization.CultureInfo.InvariantCulture)+".png"));}Scale(new SizeF(1/factor,1/factor));ClientSize=saved;}
   using(var dialog=CreateResultDialog(L.Get("Text133"),"",new List<string>{Problems.Explain(new UnauthorizedAccessException("test"))},"Test exception details")){dialog.Show();Application.DoEvents();using(var image=new Bitmap(dialog.ClientSize.Width,dialog.ClientSize.Height)){dialog.Controls[0].DrawToBitmap(image,new Rectangle(Point.Empty,dialog.ClientSize));image.Save(Path.Combine(output,original+"-error.png"));}dialog.Close();}
   using(var dialog=Dialogs.Create(L.Get("ReviewInstall")+Environment.NewLine+game.Text+Environment.NewLine+"Alpha test mod · 1.0.0 → 2.0.0",L.Get("Text118"),MessageBoxButtons.YesNo,MessageBoxIcon.Question)){dialog.Show();Application.DoEvents();AssertExperience(((Button)dialog.CancelButton).DialogResult==DialogResult.No,"confirmation defaults to cancel",results);using(var image=new Bitmap(dialog.ClientSize.Width,dialog.ClientSize.Height)){dialog.Controls[0].DrawToBitmap(image,new Rectangle(Point.Empty,dialog.ClientSize));image.Save(Path.Combine(output,original+"-confirmation.png"));}dialog.Close();}
   ChangeLanguage(2);AssertExperience(Data.Read<Settings>(Path.Combine(store,"settings.json")).language=="zh-CN","language saved without rescanning or changing mods",results);
  }
 }
